/** Top-level categories as shown in the live dropdown (parents only). */
export const TOP_CATEGORIES = CATALOG.filter((item) => !item.parent)

export function getCatalogItem(slug: string) {
  return CATALOG.find((item) => item.slug === slug)
}

export function getChildren(parentSlug: string) {
  return CATALOG.filter((item) => item.parent === parentSlug)
}

